INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''pattern making'' in apparel manufacturing?', '["Creating the template pieces (patterns) that define the shape of each garment component before cutting","Applying decorative fabric prints","The final pressing of a finished garment","Sewing two fabric pieces together"]'::jsonb, 'Creating the template pieces (patterns) that define the shape of each garment component before cutting', 'Pattern making translates a garment design into flat template pieces (front, back, sleeve, collar, etc.) that define the exact shape needed for each fabric piece before cutting begins.', 1, '{"pattern-making"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''grading'' in the context of garment patterns?', '["Proportionally resizing a base pattern to create the full range of sizes (S, M, L, XL, etc.)","Rating the quality of a finished garment","Sorting fabric rolls by color shade","Measuring a garment''s final weight"]'::jsonb, 'Proportionally resizing a base pattern to create the full range of sizes (S, M, L, XL, etc.)', 'Grading takes a base (sample) size pattern and systematically increases or decreases its dimensions at defined grade points to produce the complete size range needed for production.', 1, '{"pattern-grading"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''marker'' in garment cutting?', '["A layout plan showing how pattern pieces are arranged on the fabric to minimize waste before cutting","A pen used to mark defects on fabric","A device that measures fabric width","A label sewn into the finished garment"]'::jsonb, 'A layout plan showing how pattern pieces are arranged on the fabric to minimize waste before cutting', 'A marker is the arrangement plan of all pattern pieces (for one or multiple sizes) laid out on the fabric width, optimized to use the least fabric possible before the cutting process begins.', 1, '{"marker-making"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''marker efficiency'' (or marker utilization %) a measure of?', '["The percentage of fabric area actually used by pattern pieces versus total fabric area in the marker","The speed at which a marker is created by the pattern department","The exact number of garments cut per hour","The color accuracy of the marker layout"]'::jsonb, 'The percentage of fabric area actually used by pattern pieces versus total fabric area in the marker', 'Marker efficiency % = (area covered by pattern pieces / total marker area) × 100 — a higher percentage means less fabric wasted as unused scrap between pattern pieces, directly affecting fabric cost.', 1, '{"marker-efficiency"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''spreading'' in the garment cutting room?', '["Laying multiple layers of fabric on top of each other on the cutting table before cutting, to cut many garment pieces at once","Ironing fabric flat before sewing","Distributing finished garments to different stores","Applying fabric softener during finishing"]'::jsonb, 'Laying multiple layers of fabric on top of each other on the cutting table before cutting, to cut many garment pieces at once', 'Spreading stacks many fabric layers (a ''lay'') on the cutting table so that when the marker is cut once through all layers, many identical garment pieces are produced simultaneously — dramatically improving cutting efficiency versus cutting one layer at a time.', 1, '{"fabric-spreading"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'Why is precise, wrinkle-free fabric spreading important before cutting?', '["Wrinkles or misaligned layers can cause pattern pieces to be cut slightly out of shape or size, leading to fit defects in the finished garment","Spreading technique has no effect on cutting accuracy at all","Wrinkled fabric always cuts more accurately than flat fabric","Spreading only affects fabric color, not cutting precision"]'::jsonb, 'Wrinkles or misaligned layers can cause pattern pieces to be cut slightly out of shape or size, leading to fit defects in the finished garment', 'If fabric layers aren''t spread flat and aligned, the cutting blade may cut through distorted fabric, producing pieces that are slightly the wrong shape/size — causing fit problems or seam mismatches once sewn.', 1, '{"fabric-spreading"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''lay height'' (ply height) in fabric spreading, and why is there a practical limit to it?', '["The number of fabric layers stacked for one cutting session; too many layers can cause cutting inaccuracy and blade strain","The physical height of the cutting table itself, unrelated to fabric layers","The height of the finished garment when laid flat","A measure of fabric GSM, unrelated to spreading"]'::jsonb, 'The number of fabric layers stacked for one cutting session; too many layers can cause cutting inaccuracy and blade strain', 'Lay height refers to how many fabric plies are stacked together for cutting; while more layers improve cutting efficiency (more garments per cut), too many layers can reduce cutting accuracy (blade drift/heat) and strain cutting equipment, so a practical maximum height is followed based on fabric type and cutting method.', 2, '{"lay-height"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is the purpose of a ''fusing'' machine in garment production?', '["Applying heat and pressure to permanently bond an interlining material to fabric (e.g., collars, cuffs) for structure and stability","Sewing two fabric pieces together with thread","Cutting multiple fabric layers simultaneously","Pressing the final finished garment"]'::jsonb, 'Applying heat and pressure to permanently bond an interlining material to fabric (e.g., collars, cuffs) for structure and stability', 'A fusing machine applies controlled heat, pressure, and time to bond a fusible interlining (with heat-activated adhesive) onto fabric — commonly used for collars, cuffs, and plackets to give them structure and crispness.', 1, '{"fusing"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why must fusing temperature, pressure, and dwell time all be carefully controlled together, rather than just one parameter?', '["The adhesive bond quality depends on the correct combination of all three; getting one wrong (even if others are correct) can cause poor bonding, fabric damage, or an inconsistent finish","Only temperature matters for fusing; pressure and time have no effect on bond quality","Fusing parameters have no relationship to each other and can each be set completely independently with no consequence","Higher temperature always compensates for insufficient pressure or time with no downside"]'::jsonb, 'The adhesive bond quality depends on the correct combination of all three; getting one wrong (even if others are correct) can cause poor bonding, fabric damage, or an inconsistent finish', 'Fusing adhesive activation depends on the combined effect of heat, pressure, and time — insufficient temperature/time causes weak bonding (interlining separates later), too much heat/pressure can scorch or flatten fabric texture, so all three must be balanced together for a correct, durable fuse.', 2, '{"fusing-parameters"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is an ''overlock'' (serger) stitch primarily used for in garment sewing?', '["Trimming and enclosing raw fabric edges with thread to prevent fraying, often used on seam allowances","Attaching buttons to a garment","Creating a completely invisible hem","Embroidering decorative patterns"]'::jsonb, 'Trimming and enclosing raw fabric edges with thread to prevent fraying, often used on seam allowances', 'Overlock (serger) machines trim the raw fabric edge and simultaneously wrap thread around it, preventing the cut edge from fraying — commonly used to finish seam allowances, especially on knit and woven garments.', 1, '{"overlock-stitch"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''lockstitch'' machine typically used for in garment sewing, compared to an overlock machine?', '["Creating a strong, straight seam using two interlocking threads (needle + bobbin), commonly used for main seams and topstitching","Only trimming and finishing raw fabric edges","Only attaching woven labels to garments","Only cutting fabric, not stitching it"]'::jsonb, 'Creating a strong, straight seam using two interlocking threads (needle + bobbin), commonly used for main seams and topstitching', 'A lockstitch machine forms a straight, secure seam by interlocking a needle thread with a bobbin thread — the standard machine for main structural seams, topstitching, and most general garment construction.', 1, '{"lockstitch"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''SAM'' (Standard Allowed Minute) used to measure in garment production?', '["The standard time (in minutes) allowed to complete one specific sewing operation, used for production planning and costing","The exact seam allowance width in a garment pattern","The total number of workers needed on a production line","The final quality grade of a finished garment"]'::jsonb, 'The standard time (in minutes) allowed to complete one specific sewing operation, used for production planning and costing', 'SAM (Standard Allowed Minute/Minute Allowance) is a work-study-derived time value for each sewing operation, used to plan line balancing, estimate labor cost, calculate production targets, and determine worker efficiency.', 1, '{"sam-standard-time"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why is SAM important for calculating a garment''s labor cost?', '["SAM (total minutes needed to make the garment) combined with the labor rate per minute directly determines the labor cost component of that garment","SAM only affects fabric cost, not labor cost","SAM has no relationship to any cost calculation in garment manufacturing","SAM is used exclusively for quality inspection, unrelated to costing"]'::jsonb, 'SAM (total minutes needed to make the garment) combined with the labor rate per minute directly determines the labor cost component of that garment', 'Labor cost per garment = total SAM (sum of all operation times) × cost per minute (based on wage rates and line efficiency) — making SAM a foundational input for accurate garment costing and pricing.', 2, '{"sam-cost-calculation"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''line balancing'' in a garment sewing production line?', '["Distributing sewing operations across workstations so each operator has a roughly equal workload, minimizing bottlenecks and idle time","Physically leveling the sewing machines on the factory floor","Balancing the color shades used across a single garment","Ensuring equal numbers of male and female workers on a line"]'::jsonb, 'Distributing sewing operations across workstations so each operator has a roughly equal workload, minimizing bottlenecks and idle time', 'Line balancing assigns sewing operations to workstations/operators so each one''s workload (in SAM) is roughly equal, preventing some operators from being overloaded (bottlenecks) while others sit idle — maximizing overall line efficiency.', 1, '{"line-balancing"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What typically causes a ''bottleneck'' on a garment sewing line?', '["A workstation/operation that takes disproportionately longer than others, causing work-in-progress to pile up before it and idle time after it","Every workstation on the line always has exactly the same processing time, so bottlenecks cannot occur","A bottleneck only refers to the physical cutting room, never the sewing line","Bottlenecks are caused exclusively by fabric color changes"]'::jsonb, 'A workstation/operation that takes disproportionately longer than others, causing work-in-progress to pile up before it and idle time after it', 'A bottleneck occurs when one operation''s cycle time significantly exceeds the others on the line — work piles up waiting for that slow station while downstream stations sit idle waiting for output, reducing the line''s overall throughput to the bottleneck''s pace.', 1, '{"bottleneck"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What does ''line efficiency %'' measure on a garment production line?', '["Actual output achieved compared to the theoretical maximum output possible given the line''s total available minutes and SAM","The percentage of workers who show up for their shift","The exact fabric utilization percentage from the cutting room","The percentage of garments that pass final quality inspection"]'::jsonb, 'Actual output achieved compared to the theoretical maximum output possible given the line''s total available minutes and SAM', 'Line efficiency % compares actual garment output to the theoretical capacity (total operator-minutes available ÷ SAM per garment) — reflecting how well the line''s available labor time is actually converted into finished output.', 2, '{"line-efficiency"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''work-in-progress'' (WIP) in a garment factory context?', '["Partially completed garments that are between processing stages (e.g., cut but not yet sewn, or sewn but not yet finished)","The total number of employees currently working a shift","Fully finished garments ready for shipment","Raw fabric that hasn''t yet been cut"]'::jsonb, 'Partially completed garments that are between processing stages (e.g., cut but not yet sewn, or sewn but not yet finished)', 'WIP refers to garment pieces/units that have started production but aren''t yet complete — sitting between stages like cutting, sewing, and finishing; excessive WIP indicates poor flow/bottlenecks and ties up capital in unfinished goods.', 1, '{"work-in-progress"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''AQL'' (Acceptable Quality Level) used for when inspecting a shipment of finished garments?', '["A statistical sampling method that defines how many defects in a sample are acceptable before the whole shipment is rejected","The exact number of garments produced per day","A measure of fabric shrinkage after washing","The percentage of cotton content required in a garment"]'::jsonb, 'A statistical sampling method that defines how many defects in a sample are acceptable before the whole shipment is rejected', 'AQL sampling inspects a statistically defined sample size from a shipment rather than every unit; if defects found exceed the acceptance number for that AQL level, the entire lot is rejected — a standard, efficient quality-control method in garment export.', 1, '{"aql-inspection"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''major defect'' versus a ''minor defect'' in garment AQL inspection terminology?', '["A major defect significantly affects the garment''s usability or appearance (likely causing customer rejection), while a minor defect is a smaller flaw less likely to affect saleability","Major and minor defects are treated identically in every AQL inspection system","A minor defect always results in immediate rejection of the entire shipment","Major defects refer only to color problems; minor defects refer only to size problems"]'::jsonb, 'A major defect significantly affects the garment''s usability or appearance (likely causing customer rejection), while a minor defect is a smaller flaw less likely to affect saleability', 'AQL inspection typically classifies defects by severity — major defects (broken zippers, large holes, significant stitching failures) are weighted more heavily than minor defects (small thread ends, slight color variation) since they more seriously affect the garment''s function or salability.', 2, '{"defect-classification"}'::text[]);
